import React, { useState, useEffect } from "react";
import axios from "axios";
import TaskForm from "../components/TaskForm";
import TaskList from "../components/TaskList";
import Pagination from "../components/Pagination";

const Dashboard = () => {
  const [tasks, setTasks] = useState([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [theme, setTheme] = useState("dark");

  const token = localStorage.getItem("token");

  const fetchTasks = async (pageNum = 1) => {
    const { data } = await axios.get(`/api/tasks?page=${pageNum}&limit=5`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    setTasks(data);
    setPage(pageNum);
    setTotalPages(3); // Example: adjust based on backend count
  };

  const addTask = async (task) => {
    await axios.post("/api/tasks", task, {
      headers: { Authorization: `Bearer ${token}` },
    });
    fetchTasks(page);
  };

  const updateTask = async (id, updates) => {
    await axios.put(`/api/tasks/${id}`, updates, {
      headers: { Authorization: `Bearer ${token}` },
    });
    fetchTasks(page);
  };

  const deleteTask = async (id) => {
    await axios.delete(`/api/tasks/${id}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    fetchTasks(page);
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  useEffect(() => {
    document.body.className = theme;
  }, [theme]);

  return (
    <div className="container">
      <h2>Dashboard</h2>
      <button onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>
        {theme === "dark" ? "🌞 Light Mode" : "🌙 Dark Mode"}
       </button>
      <TaskForm onAdd={addTask} />
      <TaskList tasks={tasks} onUpdate={updateTask} onDelete={deleteTask} />
      <div className="pagination">
        <Pagination currentPage={page} totalPages={totalPages} onPageChange={fetchTasks} />
      </div>
    </div>
  );
};

export default Dashboard;
